INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `priority`, `active`, `modified`, `revision`, `cloud_id`, `condition_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 10, 0, '2025-07-04 03:46:12', 2, NULL, 0),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 10, 0, '2025-07-04 03:46:12', 2, NULL, 0),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 10, 0, '2025-07-04 03:46:12', 2, NULL, 0),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 10, 0, '2025-07-04 03:46:12', 2, NULL, 0),
(6, 'Shortcode lista de autores', '', 'function list_all_authors() {\n    $args = array(\n        \'role__in\' => array(\'Author\', \'Editor\', \'Administrator\'),\n        \'orderby\' => \'display_name\',\n        \'order\'   => \'ASC\',\n        \'number\'  => -1\n    );\n\n    $authors = get_users($args);\n    $output = \'<section class=\"authors-list\"><ul class=\"items\">\';\n    $items = \'\';\n\n    foreach ($authors as $author) {\n        $author_url = get_author_posts_url($author->ID);\n        $avatar = get_avatar($author->ID, 64);\n        $items .= \'<li class=\"item\">\';\n        $items .= \'<a href=\"\' . esc_url($author_url) . \'\">\';\n        $items .= $avatar;\n        $items .= \'<p>\' . esc_html($author->display_name) . \'</p>\';\n        $items .= \'</a>\';\n        $items .= \'</li>\';\n    }\n\n    $output .= $items;\n    $output .= \'</ul></section>\';\n    return $output;\n}\n\nadd_shortcode(\'publishpress_authors_custom_snippet_list_all_authors\', \'list_all_authors\');', '', 'global', 10, 1, '2025-07-10 11:44:23', 22, NULL, 0),
(7, 'post_type video define formato do html', '', 'function adicionar_video_apos_titulo_com_shortcode($content) {\n    if (is_singular(\'video\') && in_the_loop() && is_main_query()) {\n        // Pega o valor do campo Pods (deve ser a URL do vídeo)\n        $video_url = pods_field_display(\'video\', get_the_ID(), \'video\');\n\n        if (!empty($video_url)) {\n            // Monta o player de vídeo com o shortcode nativo do WP\n            $video_html  = \'<figure class=\"wp-block-video\">\';\n            $video_html .= \'<video controls preload=\"metadata\" src=\"\' . esc_url($video_url) . \'\"></video>\';\n            $video_html .= \'</figure>\';\n\n            // Adiciona o player antes do conteúdo do post\n            return $video_html . $content;\n        }\n    }\n\n    return $content;\n}\nadd_filter(\'the_content\', \'adicionar_video_apos_titulo_com_shortcode\');', '', 'global', 10, 1, '2025-08-01 00:51:14', 38, NULL, 0),
(8, 'post type video desabilitar excerpt', '', 'function bloquear_excerpt_para_video($excerpt) {\n    if (is_singular(\'video\')) {\n        return \'\'; // limpa o resumo automático\n    }\n\n    return $excerpt;\n}\nadd_filter(\'get_the_excerpt\', \'bloquear_excerpt_para_video\');\n', '', 'global', 10, 1, '2025-08-01 00:25:45', 5, NULL, 0),
(9, 'post type video permite apenas texto', '', 'function limitar_blocos_gutenberg_para_video($allowed_blocks, $editor_context) {\n    if (!empty($editor_context->post) && $editor_context->post->post_type === \'video\') {\n        return array(\n            \'core/paragraph\', // apenas texto simples\n        );\n    }\n\n    return $allowed_blocks;\n}\nadd_filter(\'allowed_block_types_all\', \'limitar_blocos_gutenberg_para_video\', 10, 2);\n', '', 'global', 10, 1, '2025-07-31 23:55:48', 7, NULL, 0),
(10, 'post type posts list all posts HTML authorsPress', '', 'function listar_todos_os_posts_com_estilo_authorpress() {\n    $args = array(\n        \'post_type\' => \'post\', // ou \'post\' se quiser listar posts normais\n        \'posts_per_page\' => -1,\n    );\n\n    $query = new WP_Query($args);\n    ob_start();\n\n    if ($query->have_posts()) {\n        echo \'<div class=\"ppma-page-content list ast-separate-container\">\';\n\n        while ($query->have_posts()) {\n            $query->the_post();\n\n            $post_id = get_the_ID();\n            $title = get_the_title();\n            $permalink = get_permalink();\n            $thumbnail = get_the_post_thumbnail_url($post_id, \'medium\'); // ou \'full\'\n            $date = get_the_date(\'d/m/Y\');\n\n            echo \'<article id=\"post-\'. $post_id .\'\" class=\"ppma-article has-featured-image post-\'. $post_id .\' video type-video status-publish has-post-thumbnail hentry ast-grid-common-col ast-full-width ast-article-post remove-featured-img-padding ast-article-single\">\';\n            echo \'<div class=\"article-content\">\';\n            echo \'<div class=\"article-image\">\';\n            echo \'<img src=\"\' . $thumbnail . \'\" alt=\"\" style=\"\">\';\n            echo \'</div>\';\n\n            echo \'<div class=\"article-body\">\';\n            echo \'<header class=\"article-header\">\';\n            echo \'<h2 class=\"article-title entry-title title\">\';\n            echo \'<a href=\"\' . $permalink . \'\" rel=\"bookmark\" title=\"\' . $title . \'\">\' . $title . \'</a>\';\n            echo \'</h2>\';\n            echo \'<div class=\"article-meta post-meta meta\">\';\n            echo \'<span class=\"article-meta-item entry-meta-item post-meta-item post-meta meta\">\';\n            echo \'<span class=\"dashicons dashicons-clock\"></span>\';\n            echo \'<a href=\"\' . $permalink . \'\" rel=\"bookmark\" title=\"Published date\">\';\n            echo \'<time class=\"article-date published\" datetime=\"\' . $date . \'\">\' . $date . \'</time>\';\n            echo \'</a>\';\n            echo \'</span>\';\n            echo \'</div><!-- .article-meta -->\';\n            echo \'</header><!-- .article-header -->\';\n            echo \'<footer class=\"article-footer entry-footer post-footer\">\';\n            echo \'</footer><!-- .entry-footer -->\';\n            echo \'</div>\';\n            echo \'</div>\';\n            echo \'</article>\';\n        }\n\n        echo \'</div>\';\n    }\n	\n	wp_enqueue_style(\'ppma-styles\', plugins_url(\'publishpress-authors/src/assets/css/multiple-authors-page.css\'));\n	//wp_enqueue_style(\'ppma-styles\', plugins_url(\'publishpress-authors/src/assets/css/multiple-authors-widget.css\'));\n    wp_reset_postdata();\n    return ob_get_clean();\n}\nadd_shortcode(\'todos_os_posts_com_estilo\', \'listar_todos_os_posts_com_estilo_authorpress\');', '', 'global', 10, 0, '2025-08-02 19:31:55', 22, NULL, 0),
(11, 'posty type receitas habilitando single post imagem representativa', '', 'add_action(\'astra_entry_before\', function () {\n	if (is_singular(\'receita\') && has_post_thumbnail()) {\n		the_post_thumbnail(\'large\'); // Pode usar \'full\' se quiser\n	}\n});\n', '', 'global', 10, 0, '2025-08-03 17:08:03', 11, NULL, 0),
(12, 'post type receita fixando ultimos widgets do conteudo', '', 'add_action(\'init\', function () {\n    $post_type_object = get_post_type_object(\'receita\');\n\n    if ($post_type_object) {\n        $post_type_object->template = [\n			[\'core/paragraph\', [\'placeholder\' => \'Digite aqui o conteúdo livre…\']],\n            [\'core/heading\', [\'content\' => \'Ingredientes:\']],\n            [\'core/list\'],\n            [\'core/heading\', [\'content\' => \'Modo de preparo:\']],\n            [\'core/list\'],\n			[\'core/heading\', [\'content\' => \'Cozinhando juntos:\']],\n            [\'core/video\'],\n        ];\n\n        $post_type_object->template_lock = \'insert\';\n    }\n}, 20); // 👈 Adiciona prioridade para garantir que o Pods já tenha registrado o CPT\n', '', 'global', 10, 1, '2025-08-03 18:16:47', 10, NULL, 0),
(13, 'Carregar tradução do Astra no init', '', 'add_filter(\n    \'override_load_textdomain\',\n    function ( $override, $domain, $mofile ) {\n        if ( \'astra\' !== $domain || did_action( \'init\' ) ) {\n            return $override;\n        }\n\n        add_action(\n            \'init\',\n            static function () use ( $domain, $mofile ) {\n                load_textdomain( $domain, $mofile );\n            },\n            1\n        );\n\n        return true; // impede o carregamento precoce\n    },\n    10,\n    3\n);', '', 'global', 10, 1, '2025-11-14 12:57:09', 4, NULL, 0),
(14, 'Criando logs wp-content/debug.log', '', 'add_filter(\n    \'doing_it_wrong_trigger_error\',\n    function ( $trigger, $function, $message, $version ) {\n        if ( \'_load_textdomain_just_in_time\' === $function ) {\n            error_log( \'load_textdomain cedo: \' . wp_debug_backtrace_summary() );\n        }\n        return $trigger;\n    },\n    10,\n    4\n);', '', 'global', 10, 1, '2025-11-18 23:41:01', 2, NULL, 0),
(15, 'Limpa CSS AMP removendo prefixes e media queries não suportadas', '', 'add_action(\'wp\', function () {\n    if (is_admin() || ( function_exists(\'amp_is_request\') && ! amp_is_request() ) ) return;\n\n    ob_start(function ($html) {\n		$html = preg_replace_callback(\n            \'/(<style[^>]+>)(.*?)(<\\/style>)/is\',\n            function ($m) {\n                // Remove blocos @media (com suporte a chaves aninhadas)\n                $css = preg_replace(\'/@media[^\\{]*?\\{(?:\\s*[.#:]?[.#:,a-zA-Z0-9-\\s(>+):_^=\"[\\]]+\\{[^\\}]+\\}){0,}[^\\}]*?\\}/is\', \'\', $m[2]);\n				// remove prefixes css\n        		$css = preg_replace(\'/-?(?:webkit|moz|ms|o|moz-osx)-(?:appearance|font-smoothing)\\s*?:[^;}]+(?=;);/i\', \'\', $css);\n				$css = preg_replace(\'/-(?:webkit|moz|ms|o|moz-osx)-(?:appearance|font-smoothing)\\s*:[a-zA-Z0-9-]+/i\', \'\', $css);\n				// remove input css - (?<=[>}])[^}]+([\\s,\\}]input.*?)\\}\n				$css = preg_replace(\'/(?<=\\})(?:[^;}]+?)(?:input.*?)(?=\\})\\}/is\', \'\', $css);\n				// remove empties selectors\n				$css = preg_replace(\'/[a-zA-Z:\\]=\\[,-]+\\{\\}/i\', \'\', $css);\n				// add custom css\n				$css = preg_replace(\'/(\\/\\*# sourceURL=amp-custom.css \\*\\/)/is\', \'.site{max-width:720px;margin:0 auto;}#ast-desktop-header,.ast-header-search,.ast-button-wrap,.ast-builder-grid-row-3-equal .ast-builder-grid-row>:first-child{display:none;}.ast-builder-grid-row-3-equal .ast-builder-grid-row{grid-template-columns: repeat(2, 1fr);}$1\', $css);\n				\n				error_log($css);\n                return $m[1] . $css . $m[3];\n            },\n            $html\n        );\n\n        return $html;\n    });\n});\n', '', 'front-end', 10, 1, '2026-03-01 09:38:58', 1, NULL, 0),
(16, 'add nonce window.REST_NONCE', '', 'add_action(\'admin_footer\', function () {\n    if (!current_user_can(\'manage_options\')) return;\n    $nonce = wp_create_nonce(\'wp_rest\');\n    echo \"<script>window.REST_NONCE = \'{$nonce}\';</script>\";\n});\n', '', 'global', 10, 1, '2026-02-06 15:10:36', 1, NULL, 0);
